// Draw artisan dark ebony chopsticks resting naturally on the lower-right rim
function drawChopsticks(cx, cy, R, lightX, flicker) {
  ctx.save();
  ctx.translate(cx + R * 0.56, cy + R * 0.44);
  ctx.rotate(-0.26);

  const sticks = [
    { yOff: -R * 0.045, rot: -0.025 },
    { yOff: R * 0.042, rot: 0.018 }
  ];

  for (const st of sticks) {
    ctx.save();
    ctx.translate(0, st.yOff);
    ctx.rotate(st.rot);

    const lenL = -R * 0.52;
    const lenR = R * 1.18;
    const tipHalf = R * 0.013;
    const buttHalf = R * 0.031;

    // Cast shadow on bowl rim & table
    ctx.fillStyle = 'rgba(0, 0, 0, 0.52)';
    ctx.beginPath();
    ctx.moveTo(lenL, -tipHalf + R * 0.032);
    ctx.lineTo(lenR, -buttHalf + R * 0.048);
    ctx.lineTo(lenR, buttHalf + R * 0.048);
    ctx.lineTo(lenL, tipHalf + R * 0.032);
    ctx.closePath();
    ctx.fill();

    // Dark lacquered ebony chopstick body
    ctx.beginPath();
    ctx.moveTo(lenL, -tipHalf);
    ctx.lineTo(lenR, -buttHalf);
    ctx.quadraticCurveTo(lenR + R * 0.015, 0, lenR, buttHalf);
    ctx.lineTo(lenL, tipHalf);
    ctx.quadraticCurveTo(lenL - R * 0.012, 0, lenL, -tipHalf);
    ctx.closePath();

    const woodGrad = ctx.createLinearGradient(0, -buttHalf, 0, buttHalf);
    woodGrad.addColorStop(0, '#5a3a26');
    woodGrad.addColorStop(0.28, '#2d1c13');
    woodGrad.addColorStop(0.7, '#140c08');
    woodGrad.addColorStop(1, '#261710');
    ctx.fillStyle = woodGrad;
    ctx.fill();

    // Subtle brass/gold accent band near handle
    const bandX = R * 0.72;
    const bandW = R * 0.045;
    const bandHalf = lerp(tipHalf, buttHalf, (bandX - lenL) / (lenR - lenL));
    const goldGrad = ctx.createLinearGradient(bandX, -bandHalf, bandX, bandHalf);
    goldGrad.addColorStop(0, '#e8c47a');
    goldGrad.addColorStop(0.4, '#b88636');
    goldGrad.addColorStop(1, '#5e3f14');
    ctx.fillStyle = goldGrad;
    ctx.fillRect(bandX, -bandHalf * 0.96, bandW, bandHalf * 1.92);

    // Fine warm lacquer specular highlight along top facet
    ctx.strokeStyle = `rgba(255, 212, 162, ${(0.28 + lightX * 0.06) * flicker})`;
    ctx.lineWidth = Math.max(1, R * 0.006);
    ctx.beginPath();
    ctx.moveTo(lenL + R * 0.06, -tipHalf * 0.55);
    ctx.lineTo(lenR - R * 0.06, -buttHalf * 0.55);
    ctx.stroke();

    ctx.restore();
  }
  ctx.restore();
}

